-- ============================================================================
-- 13. DATA-INTEGRITY TRIGGERS FOR REPORT SUBTYPES
-- ============================================================================

DELIMITER $$

CREATE TRIGGER trg_accident_reports_validate_type_insert
BEFORE INSERT ON accident_reports
FOR EACH ROW
BEGIN
    DECLARE v_report_type VARCHAR(20);
    SELECT report_type INTO v_report_type
    FROM reports
    WHERE report_id = NEW.report_id;

    IF v_report_type IS NULL OR v_report_type <> 'ACCIDENT' THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'accident_reports requires a parent reports row with report_type = ACCIDENT';
    END IF;
END$$

CREATE TRIGGER trg_hazard_reports_validate_type_insert
BEFORE INSERT ON hazard_reports
FOR EACH ROW
BEGIN
    DECLARE v_report_type VARCHAR(20);
    SELECT report_type INTO v_report_type
    FROM reports
    WHERE report_id = NEW.report_id;

    IF v_report_type IS NULL OR v_report_type <> 'HAZARD' THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'hazard_reports requires a parent reports row with report_type = HAZARD';
    END IF;
END$$

CREATE TRIGGER trg_reports_prevent_type_change
BEFORE UPDATE ON reports
FOR EACH ROW
BEGIN
    IF NEW.report_type <> OLD.report_type THEN
        IF EXISTS (SELECT 1 FROM accident_reports WHERE report_id = OLD.report_id)
           OR EXISTS (SELECT 1 FROM hazard_reports WHERE report_id = OLD.report_id) THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Cannot change report_type after a subtype record has been created';
        END IF;
    END IF;
END$$

CREATE TRIGGER trg_accidents_validate_source_report_insert
BEFORE INSERT ON accidents
FOR EACH ROW
BEGIN
    DECLARE v_report_type VARCHAR(20);

    IF NEW.source_report_id IS NOT NULL THEN
        SELECT report_type INTO v_report_type
        FROM reports
        WHERE report_id = NEW.source_report_id;

        IF v_report_type IS NULL OR v_report_type <> 'ACCIDENT' THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'accidents.source_report_id must reference an ACCIDENT report';
        END IF;
    END IF;
END$$

DELIMITER ;

-- ============================================================================
-- 14. USEFUL VIEWS
-- ============================================================================

CREATE VIEW vw_report_overview AS
SELECT
    r.report_id,
    r.report_type,
    r.title,
    r.description,
    rs.status_code,
    rs.status_name,
    r.user_id,
    u.full_name AS reporter_name,
    r.location_id,
    l.latitude,
    l.longitude,
    l.landmark_name,
    l.area_name,
    r.road_segment_id,
    r.reported_at,
    r.resolved_at,
    (SELECT COUNT(*) FROM report_votes rv WHERE rv.report_id = r.report_id AND rv.vote_type = 'CONFIRM') AS confirm_votes,
    (SELECT COUNT(*) FROM report_votes rv WHERE rv.report_id = r.report_id AND rv.vote_type = 'DISPUTE') AS dispute_votes
FROM reports r
JOIN report_statuses rs ON rs.status_id = r.status_id
JOIN locations l ON l.location_id = r.location_id
LEFT JOIN users u ON u.user_id = r.user_id;

CREATE VIEW vw_latest_segment_safety_score AS
SELECT ss.*
FROM safety_scores ss
JOIN (
    SELECT road_segment_id, MAX(calculated_at) AS max_calculated_at
    FROM safety_scores
    GROUP BY road_segment_id
) latest
    ON latest.road_segment_id = ss.road_segment_id
   AND latest.max_calculated_at = ss.calculated_at;

CREATE VIEW vw_emergency_services_with_location AS
SELECT
    es.emergency_service_id,
    est.service_type_name,
    es.service_name,
    es.phone,
    es.emergency_phone,
    es.opening_hours,
    es.is_24_hours,
    es.website_url,
    es.is_verified,
    es.is_active,
    l.latitude,
    l.longitude,
    l.address_line,
    l.landmark_name,
    l.area_name,
    l.city,
    l.district
FROM emergency_services es
JOIN emergency_service_types est ON est.service_type_id = es.service_type_id
JOIN locations l ON l.location_id = es.location_id;

